package com.nthexperience.desktop;

import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.database.Cursor;import android.graphics.Color;import android.net.Uri;import android.os.*;import android.provider.CalendarContract;import android.view.*;import android.widget.*;
import org.json.*;import java.util.*;import java.text.*;import java.util.concurrent.*;

/** Local appointments plus optional read-only device calendars. Android owns reminder delivery. */
final class EightCalendar extends LinearLayout {
    static final int READ=8601,EXPORT=8602;
    final MonthCalendarView calendar;final TextView month,date;final Activity activity;final DesktopStore store;
    final LinearLayout body;final FrameLayout agenda;final Handler main=new Handler(Looper.getMainLooper());final ExecutorService worker=Executors.newSingleThreadExecutor();
    String mode="Month";boolean closed,active;AlertDialog editor,detailDialog;int generation;JSONObject pendingExport;
    EightCalendar(Context c){super(c);activity=(Activity)c;store=new DesktopStore(c);setOrientation(VERTICAL);setBackgroundColor(Color.WHITE);setContentDescription("Eight Calendar month view");TenAppearance.preserve(this);
        LinearLayout top=EightAppUi.bar(c,this,"Calendar",0xff64448e);month=Aero.text(c,"",19,Color.WHITE);top.addView(month,new LayoutParams(-2,-2));
        LinearLayout commands=EightAppUi.commands(c,this);for(String view:new String[]{"Month","Day","Week","Agenda"})commands.addView(EightAppUi.button(c,view,()->{mode=view;render();}));commands.addView(EightAppUi.button(c,"New appointment",()->edit(null)));commands.addView(EightAppUi.button(c,"Today",()->calendarToday()));commands.addView(EightAppUi.button(c,"Device calendars",this::deviceOptions));
        LinearLayout navigation=new LinearLayout(c);navigation.addView(command("‹","Previous month",()->shift(-1)),new LayoutParams(Aero.dp(c,46),Aero.dp(c,42)));date=EightAppUi.text(c,"",15);date.setGravity(Gravity.CENTER_VERTICAL);navigation.addView(date,new LayoutParams(0,Aero.dp(c,42),1));navigation.addView(command("›","Next month",()->shift(1)),new LayoutParams(Aero.dp(c,46),Aero.dp(c,42)));addView(navigation);
        body=new LinearLayout(c);addView(body,new LayoutParams(-1,0,1));agenda=new FrameLayout(c);calendar=new MonthCalendarView(c,this::update);calendar.shellStyle();addOnLayoutChangeListener((v,l,t,r,b,ol,ot,or,ob)->{if((r-l>=Aero.dp(c,600))!=(or-ol>=Aero.dp(c,600)))render();});render();
    }
    void calendarToday(){calendar.today();}
    int dp(int n){return Aero.dp(getContext(),n);}void shift(int n){if(mode.equals("Month"))calendar.offset(n);else{Calendar day=Calendar.getInstance();day.setTime(calendar.selected());day.add(Calendar.DAY_OF_MONTH,n*(mode.equals("Week")?7:1));calendar.restore(day.getTimeInMillis(),day.getTimeInMillis());}}
    TextView command(String s,String description,Runnable action){TextView v=EightAppUi.button(getContext(),s,action);v.setContentDescription(description);v.setGravity(Gravity.CENTER);return v;}
    void render(){if(closed)return;body.removeAllViews();boolean wide=getWidth()>=dp(600);body.setOrientation(wide?HORIZONTAL:VERTICAL);if(calendar.getParent() instanceof android.view.ViewGroup)((android.view.ViewGroup)calendar.getParent()).removeView(calendar);if(agenda.getParent() instanceof android.view.ViewGroup)((android.view.ViewGroup)agenda.getParent()).removeView(agenda);
        if(mode.equals("Month"))body.addView(calendar,wide?new LayoutParams(0,-1,1):new LayoutParams(-1,0,1));body.addView(agenda,wide&&mode.equals("Month")?new LayoutParams(0,-1,1):new LayoutParams(-1,0,1));update();}
    static long midnight(long when){Calendar c=Calendar.getInstance();c.setTimeInMillis(when);c.set(Calendar.HOUR_OF_DAY,0);c.set(Calendar.MINUTE,0);c.set(Calendar.SECOND,0);c.set(Calendar.MILLISECOND,0);return c.getTimeInMillis();}
    long[] range(){Calendar c=Calendar.getInstance();c.setTimeInMillis(midnight(calendar.selected().getTime()));if(mode.equals("Week"))c.add(Calendar.DAY_OF_MONTH,-Math.floorMod(c.get(Calendar.DAY_OF_WEEK)-c.getFirstDayOfWeek(),7));long from=c.getTimeInMillis();c.add(Calendar.DAY_OF_MONTH,mode.equals("Week")?7:mode.equals("Agenda")?90:1);return new long[]{from,c.getTimeInMillis()};}
    void update(){if(calendar==null||date==null||closed)return;month.setText(calendar.title());date.setText(DateFormat.getDateInstance(DateFormat.FULL).format(calendar.selected()));long[] range=range();List<JSONObject> events=new ArrayList<>();JSONArray local=EightPimStore.rows(store,EightPimModels.EVENTS);Set<Long> marks=new HashSet<>();
        for(int i=0;i<local.length();i++){JSONObject row=local.optJSONObject(i);if(row==null)continue;if(EightPimModels.displayTime(row,"start",TimeZone.getDefault())<range[1]&&EightPimModels.displayTime(row,"end",TimeZone.getDefault())>range[0])events.add(row);long day=midnight(EightPimModels.displayTime(row,"start",TimeZone.getDefault()));for(int n=0;n<367&&day<EightPimModels.displayTime(row,"end",TimeZone.getDefault());n++){marks.add(day);Calendar c=Calendar.getInstance();c.setTimeInMillis(day);c.add(Calendar.DAY_OF_MONTH,1);day=c.getTimeInMillis();}}
        calendar.eventDays(marks);show(events,range);int request=++generation;
        if(!store.prefs.getBoolean("eight_calendar_device",false)||activity.checkSelfPermission(Manifest.permission.READ_CALENDAR)!=PackageManager.PERMISSION_GRANTED)return;
        List<JSONObject> merged=new ArrayList<>(events);worker.execute(()->{String error=null;try{Uri.Builder uri=CalendarContract.Instances.CONTENT_URI.buildUpon();ContentUris.appendId(uri,Math.max(0,range[0]-86400000L));ContentUris.appendId(uri,range[1]+86400000L);String[] columns={CalendarContract.Instances.EVENT_ID,CalendarContract.Instances.TITLE,CalendarContract.Instances.BEGIN,CalendarContract.Instances.END,CalendarContract.Instances.ALL_DAY,CalendarContract.Instances.EVENT_LOCATION};try(Cursor cur=activity.getContentResolver().query(uri.build(),columns,CalendarContract.Calendars.VISIBLE+"=1",null,CalendarContract.Instances.BEGIN+" ASC")){int count=0;while(cur!=null&&cur.moveToNext()&&count++<300){JSONObject row=new JSONObject();row.put("id","device_"+cur.getLong(0)).put("title",cur.getString(1)==null?"Untitled event":cur.getString(1)).put("start",cur.getLong(2)).put("end",cur.getLong(3)).put("allDay",cur.getInt(4)!=0).put("location",cur.getString(5)==null?"":cur.getString(5)).put("device",cur.getLong(0)).put("zone","UTC");if(EightPimModels.displayTime(row,"start",TimeZone.getDefault())<range[1]&&EightPimModels.displayTime(row,"end",TimeZone.getDefault())>range[0])merged.add(row);}}}catch(Exception failure){error="Device calendar access is unavailable. Local appointments are kept.";}String message=error;main.post(()->{if(!closed&&request==generation){show(merged,range);if(message!=null)Toast.makeText(activity,message,Toast.LENGTH_LONG).show();}});});
    }
    void show(List<JSONObject> events,long[] range){events.sort(Comparator.comparingLong(a->a.optLong("start")));agenda.removeAllViews();List<String> labels=new ArrayList<>();for(JSONObject e:events)labels.add(e.optString("title")+"\n"+when(e)+(e.has("device")?" · Device calendar":"")+(e.optString("location").isEmpty()?"":"\n"+e.optString("location")));if(labels.isEmpty()){TextView empty=EightAppUi.text(activity,"No appointments for this "+(mode.equals("Agenda")?"90-day range":mode.equals("Week")?"week":"day")+".\nChoose New appointment to add one.",16);empty.setPadding(dp(20),dp(20),dp(20),0);agenda.addView(empty);}else{ListView list=EightAppUi.list(activity,labels,n->details(events.get(n)));list.setContentDescription("Calendar appointments");agenda.addView(list,new FrameLayout.LayoutParams(-1,-1));}}
    String when(JSONObject e){DateFormat d=DateFormat.getDateInstance(DateFormat.MEDIUM),t=android.text.format.DateFormat.getTimeFormat(activity);if(e.optBoolean("allDay")&&!e.optString("zone").isEmpty()){d.setTimeZone(TimeZone.getTimeZone(e.optString("zone")));t.setTimeZone(d.getTimeZone());}return d.format(new Date(e.optLong("start")))+(e.optBoolean("allDay")?" · All day":" · "+t.format(new Date(e.optLong("start")))+" - "+t.format(new Date(e.optLong("end"))));}
    void details(JSONObject row){if(row.has("device")){EightAppUi.launch(activity,new Intent(Intent.ACTION_VIEW,ContentUris.withAppendedId(CalendarContract.Events.CONTENT_URI,row.optLong("device"))));return;}LinearLayout body=EightAppUi.dialogBody(activity);EightAppUi.note(activity,body,when(row)+"\n"+row.optString("location")+"\n\n"+row.optString("notes")+"\n\nLocal appointment. Add to device calendar to configure reminders.");AlertDialog detail=Aero.dialog(activity).setTitle(row.optString("title")).setView(EightAppUi.scroll(activity,body)).setNegativeButton("Close",null).create();detailDialog=detail;
        body.addView(EightAppUi.button(activity,"Edit appointment",()->{detail.dismiss();edit(row);}));body.addView(EightAppUi.button(activity,"Add to device calendar / reminders",()->EightAppUi.launch(activity,deviceIntent(row))));body.addView(EightAppUi.button(activity,"Export .ics",()->{pendingExport=row;store.prefs.edit().putString("eight_calendar_export",row.optString("id")).apply();try{activity.startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("text/calendar").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"Appointment.ics"),EXPORT);}catch(RuntimeException e){EightAppUi.error(activity,e);}}));body.addView(EightAppUi.button(activity,"Delete appointment",()->Aero.dialog(activity).setTitle("Delete this local appointment?").setMessage("The device calendar is unchanged.").setNegativeButton("Cancel",null).setPositiveButton("Delete",(x,y)->{try{EightPimStore.delete(store,EightPimModels.EVENTS,row.optString("id"));detail.dismiss();update();}catch(JSONException e){EightAppUi.error(activity,e);}}).show()));detail.show();}
    static Intent deviceIntent(JSONObject row){long start=row.optLong("start"),end=row.optLong("end");if(row.optBoolean("allDay")){TimeZone zone=TimeZone.getTimeZone(row.optString("zone"));start=utcDay(start,zone);end=utcDay(end,zone);}return new Intent(Intent.ACTION_INSERT,CalendarContract.Events.CONTENT_URI).putExtra(CalendarContract.Events.TITLE,row.optString("title")).putExtra(CalendarContract.Events.DESCRIPTION,row.optString("notes")).putExtra(CalendarContract.Events.EVENT_LOCATION,row.optString("location")).putExtra(CalendarContract.EXTRA_EVENT_BEGIN_TIME,start).putExtra(CalendarContract.EXTRA_EVENT_END_TIME,end).putExtra(CalendarContract.EXTRA_EVENT_ALL_DAY,row.optBoolean("allDay"));}
    static long utcDay(long time,TimeZone zone){Calendar local=Calendar.getInstance(zone);local.setTimeInMillis(time);Calendar utc=Calendar.getInstance(TimeZone.getTimeZone("UTC"));utc.clear();utc.set(local.get(Calendar.YEAR),local.get(Calendar.MONTH),local.get(Calendar.DAY_OF_MONTH));return utc.getTimeInMillis();}
    void edit(JSONObject existing){JSONObject initial=existing==null?EightPimModels.create():existing;LinearLayout form=EightAppUi.dialogBody(activity);EditText title=EightAppUi.input(activity,form,"Appointment title",true);title.setText(initial.optString("title"));Calendar defaultStart=Calendar.getInstance();defaultStart.setTime(calendar.selected());defaultStart.set(Calendar.HOUR_OF_DAY,9);defaultStart.set(Calendar.MINUTE,0);defaultStart.set(Calendar.SECOND,0);defaultStart.set(Calendar.MILLISECOND,0);long start=initial.has("start")?EightPimModels.displayTime(initial,"start",TimeZone.getDefault()):defaultStart.getTimeInMillis();final long[] times={start,initial.has("end")?EightPimModels.displayTime(initial,"end",TimeZone.getDefault()):start+3600000};CheckBox all=new CheckBox(activity);all.setText("All day");all.setTextColor(0xff222222);all.setChecked(initial.optBoolean("allDay"));form.addView(all);TextView from=EightAppUi.button(activity,"",()->pick(times,0,all.isChecked(),null)),until=EightAppUi.button(activity,"",()->pick(times,1,all.isChecked(),null));Runnable labels=()->{from.setText("Starts: "+DateFormat.getDateTimeInstance(DateFormat.MEDIUM,DateFormat.SHORT).format(new Date(times[0])));until.setText("Ends: "+DateFormat.getDateTimeInstance(DateFormat.MEDIUM,DateFormat.SHORT).format(new Date(times[1])));};from.setContentDescription("Appointment start");until.setContentDescription("Appointment end");from.setOnClickListener(v->pick(times,0,all.isChecked(),labels));until.setOnClickListener(v->pick(times,1,all.isChecked(),labels));form.addView(from);form.addView(until);labels.run();all.setOnCheckedChangeListener((v,checked)->{if(checked&&midnight(times[1])<=midnight(times[0])){Calendar next=Calendar.getInstance();next.setTimeInMillis(midnight(times[0]));next.add(Calendar.DAY_OF_MONTH,1);times[1]=next.getTimeInMillis();}labels.run();});EightAppUi.note(activity,form,"All-day end date is exclusive (the following day for a one-day appointment). Device calendar handles reminders.");EditText location=EightAppUi.input(activity,form,"Appointment location",true),notes=EightAppUi.input(activity,form,"Appointment notes",false);location.setText(initial.optString("location"));notes.setText(initial.optString("notes"));AlertDialog dialog=Aero.dialog(activity).setTitle(existing==null?"New appointment":"Edit appointment").setView(EightAppUi.scroll(activity,form)).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{JSONObject row=new JSONObject(initial.toString());row.put("title",title.getText().toString()).put("start",all.isChecked()?utcDay(times[0],TimeZone.getDefault()):times[0]).put("end",all.isChecked()?utcDay(times[1],TimeZone.getDefault()):times[1]).put("allDay",all.isChecked()).put("zone",all.isChecked()?"UTC":TimeZone.getDefault().getID()).put("location",location.getText().toString()).put("notes",notes.getText().toString());EightPimStore.save(store,EightPimModels.EVENTS,row);update();dialog.dismiss();}catch(JSONException e){title.setError(e.getMessage());}}));editor=dialog;dialog.show();}
    void pick(long[] times,int index,boolean allDay,Runnable changed){Calendar c=Calendar.getInstance();c.setTimeInMillis(times[index]);new DatePickerDialog(activity,(v,y,m,d)->{c.set(y,m,d);if(allDay){times[index]=midnight(c.getTimeInMillis());if(changed!=null)changed.run();}else new TimePickerDialog(activity,(clock,h,min)->{c.set(Calendar.HOUR_OF_DAY,h);c.set(Calendar.MINUTE,min);c.set(Calendar.SECOND,0);c.set(Calendar.MILLISECOND,0);times[index]=c.getTimeInMillis();if(changed!=null)changed.run();},c.get(Calendar.HOUR_OF_DAY),c.get(Calendar.MINUTE),android.text.format.DateFormat.is24HourFormat(activity)).show();},c.get(Calendar.YEAR),c.get(Calendar.MONTH),c.get(Calendar.DAY_OF_MONTH)).show();}
    void deviceOptions(){Aero.dialog(activity).setTitle("Device calendars").setItems(new String[]{"Show device appointments (read access)","Hide device appointments","Open device calendar"},(d,n)->{if(n==2){EightAppUi.launch(activity,new Intent(Intent.ACTION_VIEW,CalendarContract.CONTENT_URI.buildUpon().appendPath("time").appendPath(String.valueOf(calendar.selected().getTime())).build()));return;}store.prefs.edit().putBoolean("eight_calendar_device",n==0).apply();if(n==0&&activity.checkSelfPermission(Manifest.permission.READ_CALENDAR)!=PackageManager.PERMISSION_GRANTED)activity.requestPermissions(new String[]{Manifest.permission.READ_CALENDAR},READ);else update();}).show();}
    void permissionResult(){if(activity.checkSelfPermission(Manifest.permission.READ_CALENDAR)!=PackageManager.PERMISSION_GRANTED)store.prefs.edit().putBoolean("eight_calendar_device",false).apply();update();}
    void result(Intent data){JSONObject row=pendingExport==null?EightPimStore.get(store,EightPimModels.EVENTS,store.prefs.getString("eight_calendar_export","")):pendingExport;pendingExport=null;store.prefs.edit().remove("eight_calendar_export").apply();if(row==null||data==null||data.getData()==null)return;Uri uri=data.getData();worker.execute(()->{try{byte[] bytes=EightPimModels.ics(row).getBytes(java.nio.charset.StandardCharsets.UTF_8);try(java.io.OutputStream out=activity.getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new java.io.IOException("Destination unavailable");out.write(bytes);}main.post(()->{if(!closed)Toast.makeText(activity,"Appointment exported.",Toast.LENGTH_SHORT).show();});}catch(Exception e){main.post(()->{if(!closed)EightAppUi.error(activity,e);});}});}
    JSONObject state(){JSONObject s=new JSONObject();GadgetLayout.put(s,"mode",mode);GadgetLayout.put(s,"month",calendar.monthTime());GadgetLayout.put(s,"selected",calendar.selected().getTime());GadgetLayout.put(s,"export",pendingExport);return s;}
    void restore(JSONObject s){if(s==null)return;String m=s.optString("mode","Month");mode=Arrays.asList("Month","Day","Week","Agenda").contains(m)?m:"Month";pendingExport=s.optJSONObject("export");calendar.restore(s.optLong("month",System.currentTimeMillis()),s.optLong("selected",System.currentTimeMillis()));render();}
    void active(boolean value){if(active==value)return;active=value;if(value)update();else generation++;}
    void close(){if(editor!=null)editor.dismiss();if(detailDialog!=null)detailDialog.dismiss();closed=true;generation++;worker.shutdownNow();main.removeCallbacksAndMessages(null);}
}
